CREATE OR REPLACE FUNCTION public.start_impersonation(p_target_user_id uuid, p_reason text, p_ticket_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_id uuid; v_ttl integer;
begin
  if (select auth.uid()) is null or not (select private.is_super_admin()) then
    raise exception 'Super Admin permission required' using errcode='42501';
  end if;
  if coalesce((select auth.jwt()->>'aal'),'aal1') <> 'aal2' then
    raise exception 'MFA assurance level 2 required' using errcode='42501';
  end if;
  if nullif(trim(p_reason),'') is null then raise exception 'Reason is required'; end if;
  if p_target_user_id=(select auth.uid()) then raise exception 'Cannot impersonate self'; end if;
  if not exists(select 1 from public.profiles where id=p_target_user_id and status='active') then raise exception 'Target user is not active'; end if;
  if exists(select 1 from public.impersonation_sessions where real_actor_user_id=(select auth.uid()) and status='active' and expires_at>now()) then
    raise exception 'Nested or concurrent impersonation is not allowed';
  end if;
  select coalesce((value #>> '{}')::integer,15) into v_ttl from public.super_admin_security_settings where key='impersonation_ttl_minutes';
  v_ttl := least(greatest(coalesce(v_ttl,15),5),60);
  insert into public.impersonation_sessions(real_actor_user_id,effective_actor_user_id,reason,ticket_reference,expires_at)
  values((select auth.uid()),p_target_user_id,p_reason,p_ticket_reference,now()+make_interval(mins=>v_ttl)) returning id into v_id;
  insert into public.privileged_security_events(event_type,real_actor_user_id,effective_actor_user_id,impersonation_session_id,reason)
  values('impersonation.started',(select auth.uid()),p_target_user_id,v_id,p_reason);
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.end_impersonation(p_session_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_target uuid;
begin
  if (select auth.uid()) is null or not (select private.is_super_admin()) then raise exception 'Super Admin permission required' using errcode='42501'; end if;
  update public.impersonation_sessions set status='ended',ended_at=now(),ended_by=(select auth.uid())
  where id=p_session_id and real_actor_user_id=(select auth.uid()) and status='active' returning effective_actor_user_id into v_target;
  if v_target is null then return false; end if;
  insert into public.privileged_security_events(event_type,real_actor_user_id,effective_actor_user_id,impersonation_session_id)
  values('impersonation.ended',(select auth.uid()),v_target,p_session_id);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_access_context(p_platform text DEFAULT 'web'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_user uuid := (select auth.uid());
  v_platform public.platform_key;
  v_profile jsonb;
  v_modules jsonb;
begin
  if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if p_platform not in ('web','android','ios') then raise exception 'Invalid platform'; end if;
  v_platform := p_platform::public.platform_key;
  select jsonb_build_object('id',p.id,'email',p.email,'full_name',p.full_name,'status',p.status,'role',r.key,'mfa_required',p.mfa_required)
  into v_profile from public.profiles p join public.roles r on r.id=p.role_id where p.id=v_user;
  if v_profile is null or v_profile->>'status'<>'active' then raise exception 'Active profile required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'key',m.key,'route',m.route_key,'state',private.resolve_module_state(m.key,v_platform),
    'can_view',private.has_module_access(m.key,'view',v_platform),
    'can_create',private.has_module_access(m.key,'create',v_platform),
    'can_update',private.has_module_access(m.key,'update',v_platform),
    'can_delete',private.has_module_access(m.key,'delete',v_platform),
    'can_approve',private.has_module_access(m.key,'approve',v_platform),
    'can_block',case when m.key='users' then private.has_module_access(m.key,'block',v_platform) else false end,
    'can_change_role',case when m.key='users' then private.has_module_access(m.key,'change_role',v_platform) else false end,
    'can_change_password',case when m.key='users' then private.has_module_access(m.key,'change_password',v_platform) else false end
  ) order by m.name),'[]'::jsonb)
  into v_modules from public.system_modules m where m.is_active=true and m.platform_scope in ('all'::public.platform_key,v_platform);
  return jsonb_build_object('profile',v_profile,'system_lock',private.get_effective_system_lock(v_platform),'modules',v_modules,'generated_at',now());
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_quotation_and_create_job(p_quotation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare q public.quotations; v_job uuid; v_warehouse uuid; v_pick_list uuid; v_requires_inventory boolean;
begin
  if not private.has_module_access('quotations','approve','web') or not private.has_module_access('jobs','create','web') then
    raise exception 'Quotation approval and job creation permissions required' using errcode='42501';
  end if;
  select * into q from public.quotations where id=p_quotation_id for update;
  if q.id is null then raise exception 'Quotation not found'; end if;
  select id into v_job from public.job_orders where quotation_id=q.id;
  if v_job is not null then return v_job; end if;
  if q.status not in ('sent','viewed','accepted') then raise exception 'Quotation is not ready for acceptance'; end if;
  update public.quotations set status='accepted',accepted_at=coalesce(accepted_at,now()) where id=q.id;
  update public.leads set stage='won',won_at=coalesce(won_at,now()) where id=q.lead_id;
  insert into public.quotation_status_history(quotation_id,from_status,to_status,changed_by)
  values(q.id,q.status,'accepted',(select auth.uid()));
  insert into public.job_orders(quotation_id,lead_id,contact_id,status,created_by)
  values(q.id,q.lead_id,q.contact_id,'new',(select auth.uid())) returning id into v_job;
  insert into public.job_order_items(job_order_id,quotation_item_id,product_id,variant_id,sku_snapshot,description,quantity,unit_price_snapshot,tax_rate_snapshot,requires_inventory)
  select v_job,qi.id,qi.product_id,qi.variant_id,qi.sku_snapshot,qi.description,qi.quantity,qi.unit_price,qi.tax_rate,
    coalesce(p.track_inventory,false)
    and p.product_type <> 'service'
    and qi.item_type <> 'service'
    and qi.variant_id is not null
    and qi.quantity > 0
  from public.quotation_items qi left join public.products p on p.id=qi.product_id where qi.quotation_id=q.id;
  select exists(
    select 1 from public.job_order_items
    where job_order_id=v_job and requires_inventory=true
      and variant_id is not null and quantity > 0
  ) into v_requires_inventory;

  insert into public.tasks(title,description,task_type,job_order_id,status,priority,created_by)
  values('Schedule installation','Confirm appointment and assign installer','installation',v_job,'open','high',(select auth.uid()));

  if v_requires_inventory then
    insert into public.tasks(title,description,task_type,job_order_id,status,priority,created_by)
    values('Prepare materials','Prepare and pick required products','warehouse',v_job,'open','high',(select auth.uid()));
    select id into v_warehouse from public.warehouses where active=true order by created_at,id limit 1;
  end if;

  if v_requires_inventory and v_warehouse is not null then
    insert into public.stock_reservations(job_order_id,job_order_item_id,variant_id,warehouse_id,quantity)
    select v_job,ji.id,ji.variant_id,v_warehouse,ji.quantity from public.job_order_items ji
    where ji.job_order_id=v_job and ji.requires_inventory=true and ji.variant_id is not null and ji.quantity > 0;
    insert into public.pick_lists(job_order_id,warehouse_id,created_by) values(v_job,v_warehouse,(select auth.uid())) returning id into v_pick_list;
    insert into public.pick_list_items(pick_list_id,reservation_id,variant_id,quantity_required)
    select v_pick_list,sr.id,sr.variant_id,sr.quantity
    from public.stock_reservations sr
    where sr.job_order_id=v_job and sr.warehouse_id=v_warehouse
      and sr.job_order_item_id is not null and sr.status='active'
      and sr.quantity > 0;
  end if;
  return v_job;
end $function$

CREATE OR REPLACE FUNCTION public.allocate_payment(p_payment_id uuid, p_invoice_id uuid, p_amount numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare pay public.payments; inv public.invoices; v_used numeric; v_id uuid;
begin
  if not private.has_module_access('billing','update','web') then raise exception 'Billing update permission required' using errcode='42501'; end if;
  if p_amount<=0 then raise exception 'Allocation must be positive'; end if;
  select * into pay from public.payments where id=p_payment_id for update;
  select * into inv from public.invoices where id=p_invoice_id for update;
  if pay.id is null or inv.id is null then raise exception 'Payment or invoice not found'; end if;
  if pay.contact_id<>inv.contact_id then raise exception 'Payment and invoice contacts differ'; end if;
  select coalesce(sum(amount),0) into v_used from public.payment_allocations where payment_id=pay.id;
  if v_used+p_amount>pay.amount then raise exception 'Allocation exceeds unallocated payment amount'; end if;
  if p_amount>inv.balance_due then raise exception 'Allocation exceeds invoice balance'; end if;
  insert into public.payment_allocations(payment_id,invoice_id,amount,allocated_by)
  values(pay.id,inv.id,p_amount,(select auth.uid())) returning id into v_id;
  update public.invoices set amount_paid=amount_paid+p_amount,balance_due=balance_due-p_amount,
    status=case when balance_due-p_amount=0 then 'paid' when amount_paid+p_amount>0 then 'part_paid' else status end
  where id=inv.id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.record_stock_movement(p_client_event_id text, p_movement_type text, p_variant_id uuid, p_quantity numeric, p_from_warehouse_id uuid DEFAULT NULL::uuid, p_from_location_id uuid DEFAULT NULL::uuid, p_to_warehouse_id uuid DEFAULT NULL::uuid, p_to_location_id uuid DEFAULT NULL::uuid, p_reference_type text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_id uuid; v_balance public.inventory_balances;
begin
  if not private.has_module_access('inventory','update','web') then raise exception 'Inventory update permission required' using errcode='42501'; end if;
  if p_quantity<=0 then raise exception 'Quantity must be positive'; end if;
  select id into v_id from public.stock_movements where client_event_id=p_client_event_id;
  if v_id is not null then return v_id; end if;
  if p_from_warehouse_id is not null then
    select * into v_balance from public.inventory_balances
    where variant_id=p_variant_id and warehouse_id=p_from_warehouse_id and location_id is not distinct from p_from_location_id for update;
    if v_balance.id is null or v_balance.quantity_on_hand-v_balance.quantity_reserved<p_quantity then raise exception 'Insufficient available stock'; end if;
    update public.inventory_balances set quantity_on_hand=quantity_on_hand-p_quantity where id=v_balance.id;
  end if;
  if p_to_warehouse_id is not null then
    insert into public.inventory_balances(variant_id,warehouse_id,location_id,quantity_on_hand)
    values(p_variant_id,p_to_warehouse_id,p_to_location_id,p_quantity)
    on conflict (variant_id,warehouse_id,(coalesce(location_id,'00000000-0000-0000-0000-000000000000'::uuid)))
    do update set quantity_on_hand=public.inventory_balances.quantity_on_hand+excluded.quantity_on_hand;
  end if;
  if p_from_warehouse_id is null and p_to_warehouse_id is null then raise exception 'Movement requires a source or destination'; end if;
  insert into public.stock_movements(client_event_id,movement_type,variant_id,from_warehouse_id,from_location_id,to_warehouse_id,to_location_id,quantity,
    reference_type,reference_id,notes,created_by)
  values(p_client_event_id,p_movement_type,p_variant_id,p_from_warehouse_id,p_from_location_id,p_to_warehouse_id,p_to_location_id,p_quantity,
    p_reference_type,p_reference_id,p_notes,(select auth.uid())) returning id into v_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION private.update_own_profile(p_full_name text, p_phone text, p_avatar_path text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_row public.profiles;
begin
  if (select auth.uid()) is null then raise exception 'Authentication required' using errcode='42501'; end if;
  update public.profiles set full_name=p_full_name,phone=p_phone,avatar_path=p_avatar_path
  where id=(select auth.uid()) and status='active' returning * into v_row;
  if v_row.id is null then raise exception 'Active profile required' using errcode='42501'; end if;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION private.admin_update_user_access(p_user_id uuid, p_role_key text, p_status account_status)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_target_role text; v_target_status public.account_status; v_role_id uuid; v_owner boolean:=private.is_super_admin();
BEGIN
 if v_actor is null or private.current_role_key() is null then raise exception 'Active session required' using errcode='42501'; end if;
 if p_role_key is null or p_status is null then raise exception 'Role and status are required'; end if;
 select r.key,p.status into v_target_role,v_target_status from public.profiles p join public.roles r on r.id=p.role_id where p.id=p_user_id for update of p;
 if not found then raise exception 'User not found'; end if;
 if v_target_role='super_admin' and (p_role_key<>v_target_role or p_status<>'active') then raise exception 'Super Admin account is protected' using errcode='42501'; end if;
 if p_role_key='super_admin' and v_target_role<>'super_admin' then raise exception 'Additional Super Admin accounts are not permitted' using errcode='42501'; end if;
 if not v_owner then
   if p_user_id=v_actor then raise exception 'Cannot change own role or account status' using errcode='42501'; end if;
   if p_role_key<>v_target_role and not private.has_module_access('users','change_role','web') then raise exception 'User role-change permission required' using errcode='42501'; end if;
   if p_status<>v_target_status and not private.has_module_access('users','block','web') then raise exception 'User blocking permission required' using errcode='42501'; end if;
   if p_role_key=v_target_role and p_status=v_target_status and not
     (private.has_module_access('users','change_role','web') or private.has_module_access('users','block','web'))
   then raise exception 'Account management permission required' using errcode='42501'; end if;
 end if;
 select id into v_role_id from public.roles where key=p_role_key and active;
 if v_role_id is null then raise exception 'Invalid role'; end if;
 update public.profiles set role_id=v_role_id,status=p_status,
 deactivated_at=case when p_status=v_target_status then deactivated_at when p_status='deactivated' then now() else null end where id=p_user_id;
 insert into public.privileged_security_events(event_type,real_actor_user_id,effective_actor_user_id,target_type,target_id,metadata)
 values('user.access_changed',v_actor,p_user_id,'profile',p_user_id::text,
 jsonb_build_object('old_role',v_target_role,'role',p_role_key,'old_status',v_target_status,'status',p_status));
 return true;
END $function$

CREATE OR REPLACE FUNCTION public.crm_job_workflow_command(p_job_id text, p_revision bigint, p_operation text, p_payload jsonb, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare actor uuid:=auth.uid(); j jsonb; before_job jsonb; ts jsonb; result jsonb; plan jsonb; s jsonb; old_line jsonb; line jsonb; receipt private.crm_job_workflow_operations; hash text:=md5(jsonb_build_array(p_job_id,p_revision,p_operation,p_payload)::text); reason text:=trim(coalesce(p_payload->>'reason','')); qty numeric; required numeric; target numeric; typ text; stage_id text; stage_kind text; current_stage jsonb; quote jsonb; lead jsonb; ev jsonb; new_tasks jsonb; source_stage jsonb; row record; allowed text[]; manager_id text; billing_lines jsonb; tax_rate numeric; prices numeric[]; bill_line jsonb; next_number bigint;
begin
 if actor is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) or coalesce(private.current_role_key(),'') not in ('super_admin','admin','manager') or not private.has_module_access('jobs','view','web') or not private.has_module_access('jobs',case when p_operation in ('create','from_quote') then 'create' else 'update' end,'web') then raise exception 'Current management job permission required' using errcode='42501';end if;
 if p_operation is null or p_operation not in ('create','from_quote','product','stage','reconcile','reopen') then raise exception 'Unknown workflow operation' using errcode='22023';end if;
 if p_operation_id is null or nullif(trim(p_job_id),'') is null or length(reason)<1 or p_revision is null or p_revision<0 or jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'Operation id, job id, nonnegative revision and reason required' using errcode='22023';end if;
 allowed:=case p_operation
  when 'from_quote' then array['quoteId','reason','installerId','installationDate']
  when 'create' then array['customer','phone','address','postcode','workType','installerId','installationDate','reason']
  when 'product' then array['id','lineId','productId','name','sku','quantityRequired','unitGross','cancelled','priceConfirmed','fulfilmentSource','dependentTaskIds','reason']
  when 'stage' then array['id','stageId','name','description','type','after','applicable','taskTitle','assignedTo','requiredEvidence','requiresStock','reason']
  when 'reopen' then array['reason','target'] else array['reason'] end;
 if exists(select 1 from jsonb_object_keys(p_payload) k where not k=any(allowed)) then raise exception 'Unexpected field for workflow operation %',p_operation using errcode='22023';end if;
 if exists(select 1 from jsonb_each(p_payload) x where x.key in ('cancelled','applicable','requiresStock','priceConfirmed') and jsonb_typeof(x.value)<>'boolean') then raise exception 'Workflow flags must be booleans' using errcode='22023';end if;
 if p_payload ? 'dependentTaskIds' and (jsonb_typeof(p_payload->'dependentTaskIds')<>'array' or exists(select 1 from jsonb_array_elements(p_payload->'dependentTaskIds') x where jsonb_typeof(x)<>'string')) then raise exception 'Task dependencies must be an array of text ids' using errcode='22023';end if;
 if p_payload ? 'workType' and p_payload->>'workType' not in ('repair','installation','supply') then raise exception 'Invalid work type' using errcode='22023';end if;
 if p_payload ? 'fulfilmentSource' and p_payload->>'fulfilmentSource' not in ('company','customer') then raise exception 'Invalid fulfilment source' using errcode='22023';end if;
 if p_payload ? 'assignedTo' and nullif(p_payload->>'assignedTo','') is not null and not exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where p.id::text=p_payload->>'assignedTo' and p.status='active' and r.active) then raise exception 'Choose an active task assignee';end if;
 if p_payload ? 'requiredEvidence' and p_payload->>'requiredEvidence' not in ('none','before','after') then raise exception 'Invalid evidence requirement' using errcode='22023';end if;
 if nullif(p_payload->>'installationDate','') is not null and not isfinite((p_payload->>'installationDate')::timestamptz) then raise exception 'A valid scheduled date is required';end if;
 if p_operation in ('create','from_quote') and p_revision<>0 then raise exception 'New jobs require revision zero' using errcode='40001';end if;

 perform pg_advisory_xact_lock(hashtextextended('job-workflow-op/'||p_operation_id::text,0));
 select * into receipt from private.crm_job_workflow_operations where id=p_operation_id;
 if found then
  if receipt.actor_id<>actor or receipt.request_hash<>hash or not receipt.complete then raise exception 'Operation id was already used with different inputs';end if;
  perform pg_advisory_xact_lock(hashtextextended('job-workflow/'||p_job_id,0));
  select data into j from public.crm_records where collection='jobs' and id=p_job_id for update;
  select coalesce(jsonb_agg(data order by id),'[]') into ts from public.crm_records where collection='tasks' and data->>'jobId'=p_job_id;
  return jsonb_build_object('job',j,'tasks',ts);
 end if;
 perform pg_advisory_xact_lock(hashtextextended('job-workflow/'||p_job_id,0));
 select data into j from public.crm_records where collection='jobs' and id=p_job_id for update;
 if p_operation in ('create','from_quote') then
  if j is not null then raise exception 'Job already exists';end if;
  if p_operation='from_quote' then
   if not private.has_module_access('quotations','view','web') or not private.has_module_access('quotations','update','web') or not private.has_module_access('leads','view','web') or not private.has_module_access('leads','update','web') then raise exception 'Quotation and lead access required' using errcode='42501';end if;
   select data into quote from public.crm_records where collection='quotes' and id=p_payload->>'quoteId' for update;
   if quote is null or quote->>'status' is distinct from 'Accepted' then raise exception 'Accepted quotation required';end if;
   if nullif(quote->>'linkedJobId','') is not null or exists(select 1 from public.crm_records where collection='jobs' and data->>'quoteId'=quote->>'id') then raise exception 'Quotation already has a job; reload its linked job';end if;
   select data into lead from public.crm_records where collection='leads' and id=quote->>'leadId' for update;
   if lead is null then raise exception 'Linked lead required';end if;
   p_payload:=p_payload||jsonb_build_object('customer',lead->>'customer','phone',lead->>'phone','address',lead->>'address','postcode',lead->>'postcode','service',lead->>'service','installationDate',coalesce(p_payload->>'installationDate',(now()+interval '7 days')::text));
  end if;
  if quote is not null then
   perform private.crm_qty(quote,'total');
   if quote->>'total' is null or jsonb_typeof(quote->'items') is distinct from 'array' then raise exception 'Quotation items and total required';end if;
   for s in select value from jsonb_array_elements(quote->'items') loop
    perform private.crm_qty(s,'quantity');perform private.crm_qty(s,'unitPrice');
    if private.crm_company_stock(s) and coalesce(s->>'active','true')<>'false' and coalesce(s->>'cancelled','false')<>'true' and coalesce(s->>'excluded','false')<>'true' and lower(coalesce(s->>'status','')) not in ('cancelled','canceled','excluded') and private.crm_qty(s,'quantity')>0 then
     if not exists(select 1 from public.product_variants v join public.products p on p.id=v.product_id where v.id::text=s->>'productId' and v.active and p.active) then raise exception 'Active inventory variant required for quotation item';end if;
    end if;
   end loop;
  end if;
  if trim(coalesce(p_payload->>'customer',''))='' then raise exception 'Customer is required';end if;
  if coalesce(p_payload->>'installerId','')<>'' and not exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where p.id::text=p_payload->>'installerId' and p.status='active' and r.key='installer') then raise exception 'Choose an active installer';end if;
  -- Serialize number allocation without adding a new business table or sequence.
  perform pg_advisory_xact_lock(hashtextextended('crm-job-number',0));
  select greatest(118,coalesce(max(case when data->>'number' ~ '^JOB-[0-9]+$' then substring(data->>'number' from 5)::bigint end),118))+1 into next_number from public.crm_records where collection='jobs';
