CREATE OR REPLACE FUNCTION public.create_or_get_direct_conversation(p_target_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_pair_key text;
  v_conversation_id uuid;
begin
  if v_actor is null or p_target_user_id is null or p_target_user_id = v_actor then
    raise exception 'A different authenticated staff user is required' using errcode = '22023';
  end if;
  if not (select private.has_module_access('chat', 'send', 'web'::public.platform_key)) then
    raise exception 'Chat send access denied' using errcode = '42501';
  end if;
  if (select count(*) from public.profiles profile where profile.id in (v_actor, p_target_user_id) and profile.status = 'active') <> 2 then
    raise exception 'Both chat participants must be active staff users' using errcode = '42501';
  end if;

  v_pair_key := least(v_actor::text, p_target_user_id::text) || ':' || greatest(v_actor::text, p_target_user_id::text);

  insert into public.chat_conversations (conversation_type, direct_pair_key, created_by)
  values ('direct', v_pair_key, v_actor)
  on conflict (direct_pair_key) where direct_pair_key is not null do nothing
  returning id into v_conversation_id;

  if v_conversation_id is null then
    select conversation.id into v_conversation_id
    from public.chat_conversations conversation
    where conversation.direct_pair_key = v_pair_key;
  end if;

  insert into public.chat_conversation_members (conversation_id, user_id, member_role, left_at, joined_at)
  values
    (v_conversation_id, v_actor, 'owner', null, now()),
    (v_conversation_id, p_target_user_id, 'member', null, now())
  on conflict (conversation_id, user_id) do update
  set left_at = null,
      joined_at = case when public.chat_conversation_members.left_at is not null then now() else public.chat_conversation_members.joined_at end,
      updated_at = now();

  return v_conversation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_group_conversation(p_title text, p_member_ids uuid[], p_job_order_id uuid DEFAULT NULL::uuid, p_task_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_conversation_id uuid;
  v_type text;
  v_requested_count integer;
  v_active_count integer;
begin
  if v_actor is null or not (select private.has_module_access('chat', 'groups.create', 'web'::public.platform_key)) then
    raise exception 'Chat group creation denied' using errcode = '42501';
  end if;
  if nullif(btrim(p_title), '') is null then
    raise exception 'Group title is required' using errcode = '22023';
  end if;
  if p_job_order_id is not null and p_task_id is not null then
    raise exception 'A conversation can reference a job or task, not both' using errcode = '22023';
  end if;
  if p_job_order_id is not null and not exists (select 1 from public.job_orders job where job.id = p_job_order_id) then
    raise exception 'Job Order not found' using errcode = '23503';
  end if;
  if p_task_id is not null and not exists (select 1 from public.tasks task where task.id = p_task_id) then
    raise exception 'Task not found' using errcode = '23503';
  end if;

  select count(distinct member_id) into v_requested_count
  from unnest(coalesce(p_member_ids, '{}'::uuid[]) || array[v_actor]) member_id;
  select count(*) into v_active_count
  from public.profiles profile
  where profile.id in (
    select distinct member_id from unnest(coalesce(p_member_ids, '{}'::uuid[]) || array[v_actor]) member_id
  ) and profile.status = 'active';
  if v_requested_count <> v_active_count then
    raise exception 'Every group member must be an active staff user' using errcode = '42501';
  end if;

  v_type := case when p_task_id is not null then 'task' when p_job_order_id is not null then 'job' else 'group' end;
  insert into public.chat_conversations
    (conversation_type, title, job_order_id, task_id, created_by)
  values
    (v_type, btrim(p_title), p_job_order_id, p_task_id, v_actor)
  returning id into v_conversation_id;

  insert into public.chat_conversation_members (conversation_id, user_id, member_role)
  select v_conversation_id,
         member_id,
         case when member_id = v_actor then 'owner' else 'member' end
  from (
    select distinct member_id from unnest(coalesce(p_member_ids, '{}'::uuid[]) || array[v_actor]) member_id
  ) members;

  return v_conversation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_chat_members(p_conversation_id uuid, p_add_user_ids uuid[] DEFAULT '{}'::uuid[], p_remove_user_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_type text;
  v_requested_count integer;
  v_active_count integer;
begin
  if v_actor is null
     or not (select private.has_module_access('chat', 'groups.create', 'web'::public.platform_key))
     or not (select private.chat_can_manage(p_conversation_id, v_actor)) then
    raise exception 'Chat membership management denied' using errcode = '42501';
  end if;
  select conversation.conversation_type into v_type
  from public.chat_conversations conversation where conversation.id = p_conversation_id;
  if v_type is null then raise exception 'Conversation not found' using errcode = 'P0002'; end if;
  if v_type = 'direct' then raise exception 'Direct conversation membership is fixed' using errcode = '22023'; end if;
  if v_actor = any(coalesce(p_remove_user_ids, '{}'::uuid[])) then
    raise exception 'A manager cannot remove themselves through this operation' using errcode = '22023';
  end if;

  select count(distinct id), count(distinct profile.id)
  into v_requested_count, v_active_count
  from unnest(coalesce(p_add_user_ids, '{}'::uuid[])) id
  left join public.profiles profile on profile.id = id and profile.status = 'active';
  if v_requested_count <> v_active_count then
    raise exception 'Every added member must be an active staff user' using errcode = '42501';
  end if;

  update public.chat_conversation_members member
  set left_at = now(), updated_at = now()
  where member.conversation_id = p_conversation_id
    and member.user_id = any(coalesce(p_remove_user_ids, '{}'::uuid[]))
    and member.user_id <> v_actor;

  insert into public.chat_conversation_members
    (conversation_id, user_id, member_role, joined_at, left_at)
  select p_conversation_id, id, 'member', now(), null
  from (select distinct id from unnest(coalesce(p_add_user_ids, '{}'::uuid[])) id) added
  on conflict (conversation_id, user_id) do update
  set left_at = null,
      joined_at = case when public.chat_conversation_members.left_at is not null then now() else public.chat_conversation_members.joined_at end,
      updated_at = now();
end;
$function$

CREATE OR REPLACE FUNCTION public.review_chat_conversation(p_conversation_id uuid, p_reason text)
 RETURNS SETOF chat_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
begin
  if v_actor is null
     or (select private.current_role_key()) <> 'super_admin'
     or not (select private.has_module_access('chat', 'review_all', 'web'::public.platform_key)) then
    raise exception 'Privileged chat review denied' using errcode = '42501';
  end if;
  if nullif(btrim(p_reason), '') is null then
    raise exception 'A review reason is required' using errcode = '22023';
  end if;
  if not exists (select 1 from public.chat_conversations conversation where conversation.id = p_conversation_id) then
    raise exception 'Conversation not found' using errcode = 'P0002';
  end if;

  insert into public.privileged_security_events
    (event_type, real_actor_user_id, effective_actor_user_id, target_type, target_id, success, reason, metadata)
  values
    ('chat.review_all', v_actor, v_actor, 'chat_conversation', p_conversation_id::text, true, btrim(p_reason),
     jsonb_build_object('conversation_id', p_conversation_id));

  return query
  select message.* from public.chat_messages message
  where message.conversation_id = p_conversation_id
  order by message.sent_at, message.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_chat_message(p_conversation_id uuid, p_client_message_id uuid, p_body text DEFAULT NULL::text, p_message_type text DEFAULT 'text'::text, p_reply_to_message_id uuid DEFAULT NULL::uuid, p_job_order_id uuid DEFAULT NULL::uuid, p_task_id uuid DEFAULT NULL::uuid)
 RETURNS chat_messages
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_existing public.chat_messages;
  v_result public.chat_messages;
begin
  if v_actor is null
     or not (select private.has_module_access('chat', 'send', 'web'::public.platform_key))
     or not (select private.chat_is_active_member(p_conversation_id, v_actor)) then
    raise exception 'Chat send access denied' using errcode = '42501';
  end if;
  if p_message_type = 'system' and not (select private.chat_can_manage(p_conversation_id, v_actor)) then
    raise exception 'Only a conversation manager may send system messages' using errcode = '42501';
  end if;

  select message.* into v_existing
  from public.chat_messages message
  where message.sender_id = v_actor and message.client_message_id = p_client_message_id;
  if found then
    if v_existing.conversation_id is distinct from p_conversation_id
       or v_existing.body is distinct from p_body
       or v_existing.message_type is distinct from p_message_type
       or v_existing.reply_to_message_id is distinct from p_reply_to_message_id
       or v_existing.job_order_id is distinct from p_job_order_id
       or v_existing.task_id is distinct from p_task_id then
      raise exception 'client_message_id was already used with different content' using errcode = '23505';
    end if;
    return v_existing;
  end if;

  insert into public.chat_messages
    (conversation_id, sender_id, client_message_id, body, message_type,
     reply_to_message_id, job_order_id, task_id)
  values
    (p_conversation_id, v_actor, p_client_message_id, p_body, p_message_type,
     p_reply_to_message_id, p_job_order_id, p_task_id)
  returning * into v_result;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.resolve_module_state(p_module_key text, p_platform platform_key)
 RETURNS access_state
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_user uuid:=auth.uid(); v_role uuid; v_state public.access_state; v_config jsonb; v_page text:=private.crm_page_key(p_module_key);
BEGIN
 if private.current_role_key() is null then return 'disabled'; end if;
 if private.is_super_admin() then return 'enabled'; end if;
 if p_module_key='master_control' then return 'disabled'; end if;
 select role_id into v_role from public.profiles where id=v_user;
 if not exists(select 1 from public.system_modules where key=p_module_key and is_active) then return 'disabled'; end if;
 if exists(select 1 from public.system_lock_rules l where l.is_locked
 and (l.starts_at is null or l.starts_at<=now()) and (l.ends_at is null or l.ends_at>now())
 and (l.scope='global' or (l.scope='platform' and l.platform=p_platform))) then return 'locked'; end if;
 select data into v_config from public.crm_records where collection='accessControl' and id='_';
 if v_config#>array['locks','pages',v_page]='true'::jsonb then return 'locked'; end if;
 if v_config#>array['global','pages',v_page]='false'::jsonb
 or v_config#>array['users',v_user::text,'pages',v_page]='false'::jsonb then return 'disabled'; end if;
 if exists(select 1 from public.module_access_rules mar join public.system_modules sm on sm.id=mar.module_id
 where sm.key=p_module_key and mar.scope_type='global' and mar.access_state in ('locked','disabled')
 and mar.platform in ('all'::public.platform_key,p_platform)
 and (mar.starts_at is null or mar.starts_at<=now()) and (mar.ends_at is null or mar.ends_at>now()))
 then return 'locked'; end if;
 select mar.access_state into v_state from public.module_access_rules mar join public.system_modules sm on sm.id=mar.module_id
 where sm.key=p_module_key and sm.is_active and mar.platform in ('all'::public.platform_key,p_platform)
 and (mar.starts_at is null or mar.starts_at<=now()) and (mar.ends_at is null or mar.ends_at>now())
 and ((mar.scope_type='user' and mar.user_id=v_user) or (mar.scope_type='role' and mar.role_id=v_role) or mar.scope_type='global')
 order by case mar.scope_type when 'user' then 3 when 'role' then 2 else 1 end desc,
 case when mar.platform=p_platform then 1 else 0 end desc,mar.updated_at desc limit 1;
 return coalesce(v_state,'enabled');
END $function$

CREATE OR REPLACE FUNCTION private.crm_upgrade_require(p_module text, p_action text, p_management boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE u uuid:=(select auth.uid());
BEGIN
 IF u IS NULL OR NOT private.has_module_access(p_module,p_action,'web') OR private.current_role_key() IS NULL
 THEN RAISE EXCEPTION 'Active authenticated session and module permission required' USING ERRCODE='42501'; END IF;
 IF p_management AND private.current_role_key() NOT IN ('super_admin','admin','manager')
 THEN RAISE EXCEPTION 'Management role required' USING ERRCODE='42501'; END IF;
 RETURN u;
END $function$

CREATE OR REPLACE FUNCTION private.has_module_access(p_module_key text, p_action text DEFAULT 'view'::text, p_platform platform_key DEFAULT 'web'::platform_key)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_user uuid:=auth.uid(); v_role_id uuid; v_role text:=private.current_role_key(); v_effect public.permission_effect; v_state public.access_state;
BEGIN
 if v_role is null then return false; end if;
 if private.is_super_admin() then return true; end if;
 if p_module_key='master_control' then return false; end if;
 if p_module_key='users' and p_action in ('create','block','delete','update','change_role','change_password') and v_role not in ('admin','manager') then return false; end if;
 select role_id into v_role_id from public.profiles where id=v_user;
 v_state:=private.resolve_module_state(p_module_key,p_platform);
 if v_state in ('disabled','locked') or (v_state='readonly' and p_action<>'view') then return false; end if;
 -- A role-wide revoke of account-management powers overrides a user allow.
 if p_module_key='users' and p_action in ('update','block','delete','change_role','change_password') and exists(
   select 1 from public.role_permissions rp join public.permissions pe on pe.id=rp.permission_id
   where rp.role_id=v_role_id and pe.key=p_module_key||'.'||p_action and rp.effect='deny'
 ) then return false; end if;
 select up.effect into v_effect from public.user_permissions up join public.permissions pe on pe.id=up.permission_id
 where up.user_id=v_user and pe.key=p_module_key||'.'||p_action
 and (up.starts_at is null or up.starts_at<=now()) and (up.ends_at is null or up.ends_at>now());
 if v_effect is not null then return v_effect='allow'; end if;
 select rp.effect into v_effect from public.role_permissions rp join public.permissions pe on pe.id=rp.permission_id
 where rp.role_id=v_role_id and pe.key=p_module_key||'.'||p_action;
 return coalesce(v_effect='allow',false);
END $function$

CREATE OR REPLACE FUNCTION private.admin_delete_user(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_target_role text; v_email text;
BEGIN
 if not private.has_module_access('users','delete','web') then raise exception 'User deletion permission required' using errcode='42501'; end if;
 if p_user_id=v_actor then raise exception 'Cannot delete the active account'; end if;
 select r.key,p.email into v_target_role,v_email from public.profiles p join public.roles r on r.id=p.role_id where p.id=p_user_id for update of p;
 if not found then raise exception 'User not found'; end if;
 if v_target_role='super_admin' or lower(v_email)='annasabbas01@gmail.com' then raise exception 'Super Admin account is protected' using errcode='42501'; end if;
 if exists(select 1 from storage.objects where owner_id=p_user_id::text) then raise exception 'User owns files; reassign ownership before deletion'; end if;
 begin
   update auth.refresh_tokens set revoked=true,updated_at=now() where user_id=p_user_id::text;
   delete from auth.users where id=p_user_id;
 exception when foreign_key_violation then
   raise exception 'User has linked records or protected history. Block this account until its references can be retained or reassigned; no records were deleted.';
 end;
 insert into public.privileged_security_events(event_type,real_actor_user_id,target_type,target_id,metadata)
 values('user.deleted',v_actor,'profile',p_user_id::text,jsonb_build_object('email',v_email,'role',v_target_role));
 return true;
END $function$

CREATE OR REPLACE FUNCTION private.protect_designated_owner_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_owner boolean; v_new_super boolean; v_old_super boolean:=false;
 v_trusted boolean:=current_setting('role',true) in ('service_role','postgres')
 or (session_user='postgres' and current_setting('role',true) in ('none',''));
BEGIN
 if tg_op<>'INSERT' then select exists(select 1 from public.roles where id=old.role_id and key='super_admin') into v_old_super; end if;
 select exists(select 1 from auth.users u where u.id=case when tg_op='DELETE' then old.id else new.id end
 and lower(u.email)='annasabbas01@gmail.com') into v_owner;
 if tg_op='DELETE' then
   if v_owner or v_old_super then raise exception 'Super Admin account is protected' using errcode='42501'; end if;
   if not v_trusted and not private.has_module_access('users','delete','web') then raise exception 'User deletion permission required' using errcode='42501'; end if;
   return old;
 end if;
 select exists(select 1 from public.roles where id=new.role_id and key='super_admin') into v_new_super;
 if v_new_super and not v_owner then raise exception 'Only the designated owner may be Super Admin' using errcode='42501'; end if;
 if tg_op='UPDATE' and (v_owner or v_old_super) and
 (new.id is distinct from old.id or new.role_id is distinct from old.role_id or new.email is distinct from old.email
 or new.status is distinct from old.status or new.deactivated_at is distinct from old.deactivated_at)
 then raise exception 'Owner identity, role and status are protected' using errcode='42501'; end if;
 -- Permit only the minimal pending profile created by the nested Auth trigger.
 -- This is account bootstrap, before a CRM session can exist.
 if tg_op='INSERT' and pg_trigger_depth()=2 and not v_owner
 and new.status='pending' and new.deactivated_at is null
 and new.mfa_required=false and new.force_password_reset=false
 and exists(select 1 from public.roles r where r.id=new.role_id and r.key='installer' and r.active)
 and exists(select 1 from auth.users u where u.id=new.id and u.email=new.email)
 then return new; end if;
 if v_trusted then return new; end if;
 if (v_owner or v_old_super) and not private.is_super_admin() then
   raise exception 'Super Admin account is protected' using errcode='42501'; end if;
 if private.current_role_key() is null then raise exception 'Active session required' using errcode='42501'; end if;
 if private.is_super_admin() then return new; end if;
 if tg_op='INSERT' then raise exception 'Create users through the authorized account service' using errcode='42501'; end if;
 if new.id is distinct from old.id or new.email is distinct from old.email
 or new.mfa_required is distinct from old.mfa_required or new.force_password_reset is distinct from old.force_password_reset
 then raise exception 'Only Super Admin may change identity or security settings' using errcode='42501'; end if;
 if new.role_id is distinct from old.role_id then
   if v_actor=old.id or not private.has_module_access('users','change_role','web') then
     raise exception 'User role-change permission required' using errcode='42501'; end if;
 end if;
 if new.status is distinct from old.status or new.deactivated_at is distinct from old.deactivated_at then
   if v_actor=old.id or not private.has_module_access('users','block','web') then raise exception 'User blocking permission required' using errcode='42501'; end if;
 end if;
 if new.full_name is distinct from old.full_name or new.phone is distinct from old.phone or new.avatar_path is distinct from old.avatar_path then
   if v_actor<>old.id and not private.has_module_access('users','update','web') then raise exception 'User editing permission required' using errcode='42501'; end if;
 end if;
 return new;
END $function$
